func TestJudgeTimeoutArg(t *testing.T) {
	t.Parallel()
	if got := judgeTimeoutArg(-1); got != 0 {
		t.Errorf("judgeTimeoutArg(no-cap sentinel) = %v, want 0 (judge default applies)", got)
	}
